* Help Screen
MAP MYHELP SIZE 24x80
  FIELD AT 1,1  LEN 6  PROT BRIGHT COLOR=GREEN   "MYIF99"
  FIELD AT 1,28 LEN 24 PROT BRIGHT COLOR=GREEN   "BRICKS HELP"
  FIELD AT 2,1  LEN 8  PROT COLOR=GREEN          "MYHELP00"

  FIELD AT 4,3  LEN 74 PROT BRIGHT COLOR=TURQUOISE  "NAVIGATION KEYS"
  FIELD AT 5,3  LEN 74 PROT COLOR=GREEN  "  PF1  - LOGOFF from BRICKS"
  FIELD AT 6,3  LEN 74 PROT COLOR=GREEN  "  PF3  - Return to PREVIOUS MENU"
  FIELD AT 7,3  LEN 74 PROT COLOR=GREEN  "  PF7  - Scroll BACKWARD"
  FIELD AT 8,3  LEN 74 PROT COLOR=GREEN  "  PF8  - Scroll FORWARD"
  FIELD AT 9,3  LEN 74 PROT COLOR=GREEN  "  PF9  - This HELP screen"
  FIELD AT 10,3 LEN 74 PROT COLOR=GREEN  "  PA1  - BREAK OUT of any stuck transaction"

  FIELD AT 12,3 LEN 74 PROT BRIGHT COLOR=TURQUOISE  "MENU NAVIGATION"
  FIELD AT 13,3 LEN 74 PROT COLOR=GREEN  "  Enter a number and press ENTER to select an option."
  FIELD AT 14,3 LEN 74 PROT COLOR=GREEN  "  Only options you are authorized to run are shown."
  FIELD AT 15,3 LEN 74 PROT COLOR=GREEN  "  Your access level is shown bottom-right of each menu."

  FIELD AT 17,3 LEN 74 PROT BRIGHT COLOR=TURQUOISE  "SYSTEM TRANSACTIONS (type at blank prompt after PA1)"
  FIELD AT 18,3 LEN 74 PROT COLOR=GREEN  "  CEMT  - Master console / resource inquiry (admin)"
  FIELD AT 19,3 LEN 74 PROT COLOR=GREEN  "  CEDA  - Resource definitions (admin)"
  FIELD AT 20,3 LEN 74 PROT COLOR=GREEN  "  ISPF  - Program editor (dev group)"

  INPUT CALLFLD AT 22,1 LEN 4 PROT
  STOP          AT 22,5
  FIELD AT 24,1 LEN 78 PROT COLOR=GREEN  "Press any key to return..."
  CURSOR AT CALLFLD
ENDMAP
